  width: 36px;
  height: 36px;
  border-radius: var(--radius-button-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.15s;
}
.plugin-card__add:hover { background: var(--faktisk-blue-hover); }

/* ============================================
   Faktisk Studio-logo (CSS mask)
   ============================================ */
.faktisk-logo {
  width: 178px;
  height: 26px;
  background: #fff;
  -webkit-mask: url('logo.svg') no-repeat center / contain;
  mask: url('logo.svg') no-repeat center / contain;
  flex-shrink: 0;
}

style.css:
/* Teksting — layout etter samme mønster som de andre video-pluginene.
   Basisvariabler kommer fra shared/style.css. */

.plugin-page {
  flex: 1;
  display: grid;
  grid-template-columns: 313px 1fr;
  gap: 22px;
  overflow: hidden;
  padding: 4px;
}

.plugin-sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 0 4px;
  overflow-y: auto;
}
.plugin-sidebar__title {
  font-family: var(--font-bold);
  font-size: 27px;
  font-weight: bold;
  color: #212121;
  margin: 0;
  line-height: 1.05;
}
.plugin-sidebar__desc {
  font-family: var(--font-regular);
  font-size: 15px;
  color: #fff;
  margin: 0;
  line-height: 1.4;
}
.plugin-sidebar__spacer { flex: 1; }
.plugin-sidebar__status {
  font-size: 13px;
  color: #fff;
  min-height: 18px;
  opacity: 0.85;
}

/* ---------- Kilde ---------- */
.url-section { display: flex; flex-direction: column; gap: 6px; }
.url-section__label {
  font-family: var(--font-bold);
  font-size: 13px;
  font-weight: bold;
  color: #fff;
}
.url-section__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}
.link-btn {
  background: transparent;
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: rgba(255,255,255,0.5);
  text-underline-offset: 3px;
}
.link-btn:hover { text-decoration-color: #fff; }

.url-row {
  background: var(--bg-input);
  height: 41px;
  border-radius: var(--radius-input);
  padding: 0 4px 0 17px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.url-row__input {
  flex: 1;
  background: transparent;
  border: 0;
  outline: 0;
  height: 100%;
  font-family: var(--font-bold);
  font-size: 13px;
  color: var(--text-input);
  font-weight: bold;
  min-width: 0;
}
.url-row__input::placeholder { color: #888; font-weight: normal; }

.btn-tiny {
  background: var(--faktisk-blue);
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 13px;
  height: 30px;
  padding: 0 12px;
  border-radius: var(--radius-input);
  white-space: nowrap;
}
.btn-tiny:hover { background: var(--faktisk-blue-hover); }
.btn-tiny:disabled { opacity: 0.4; cursor: not-allowed; }
.btn-wide { width: 100%; height: 38px; }

.lab-row { display: flex; gap: 6px; }
.lab-btn { flex: 1; background: rgba(255,255,255,0.14); padding: 0 8px; }
.lab-btn:hover { background: rgba(255,255,255,0.28); }
.lab-panel {
  background: var(--bg-input);
  border-radius: var(--radius-input);
  padding: 8px;
  max-height: 220px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.lab-panel__status { font-size: 12px; color: #666; padding: 2px 4px; }
.lab-panel__status .link-btn { color: var(--faktisk-blue); text-decoration-color: rgba(0,80,252,0.4); }
.lab-panel__list { display: flex; flex-direction: column; gap: 2px; }
.lab-file {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 6px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12.5px;
  color: var(--text-input);
}
.lab-file:hover { background: rgba(0,0,0,0.08); }
.lab-file__type {
  font-size: 10px;
  font-weight: bold;
  background: rgba(0,0,0,0.12);
  border-radius: 4px;
  padding: 1px 5px;
  flex-shrink: 0;
}
.lab-file__type.video { background: var(--faktisk-blue); color: #fff; }
.lab-file__name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-bold);
  font-weight: bold;
}

/* ---------- Modellboks ---------- */
.model-box {
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-input);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.model-box__title {
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 13px;
  color: #fff;
}
.model-box__desc {
  font-size: 12px;
  line-height: 1.45;
  color: #fff;
  opacity: 0.7;
}
.model-box__reset {
  align-self: flex-start;
  font-size: 11.5px;
  margin-top: 2px;
}
.model-box__select { margin: 4px 0 2px; }

/* ---------- Prosjekt + kjør ---------- */
.project-row { display: flex; flex-direction: column; gap: 6px; }
.project-select {
  width: 100%;
  height: 36px;
  background: var(--bg-input);
  border: 0;
  border-radius: var(--radius-input);
  padding: 0 32px 0 12px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 13px;
  color: var(--text-input);
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' stroke='%23313131' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/></svg>");
  background-repeat: no-repeat;
  background-position: right 12px center;
}
.project-row .btn-tiny { width: 100%; height: 36px; }

.export-section { display: flex; flex-direction: column; gap: 8px; }
.btn-primary:disabled { opacity: 0.4; cursor: not-allowed; }
.export-progress {
  height: 8px;
  background: rgba(255,255,255,0.25);
  border-radius: 4px;
  overflow: hidden;
}
.export-progress__bar {
  height: 100%;
  width: 0;
  background: var(--faktisk-blue);
  transition: width 0.3s;
}
.export-note {
  font-size: 11.5px;
  line-height: 1.45;
  color: #fff;
  opacity: 0.6;
  margin: 0;
  min-height: 16px;
}

/* ---------- Canvas: video + segmentliste side ved side ---------- */
.plugin-canvas {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}
.canvas-split {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 12px;
  min-height: 0;
}
@media (max-width: 1100px) {
  .canvas-split { grid-template-columns: 1fr; grid-template-rows: 1fr 260px; }
}

.canvas-area {
  position: relative;
  min-height: 200px;
  background: var(--bg-letterbox);
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.canvas-video {
  display: block;
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  border-radius: 6px;
  background: #000;
}
.canvas-video:not([src]) { display: none; }
.canvas-empty {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
  pointer-events: none;
}
.canvas-empty p {
  max-width: 340px;
  line-height: 1.5;
  font-size: 14px;
  color: #fff;
  opacity: 0.75;
}

/* ---------- Segmentliste ---------- */
.segments-panel {
  display: flex;
  flex-direction: column;
  background: var(--bg-letterbox);
  border-radius: 10px;
  overflow: hidden;
  min-height: 0;
}
.segments-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 12px 16px 10px;
  border-bottom: 1px solid rgba(255,255,255,0.12);
  flex-shrink: 0;
}
.segments-title {
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 14px;
  color: #fff;
}
.segments-meta {
  font-size: 11.5px;
  color: #fff;
  opacity: 0.55;
  font-variant-numeric: tabular-nums;
}
.segments-list {
  flex: 1;
  overflow-y: auto;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.segments-empty {
  padding: 24px 16px;
  font-size: 13px;
  line-height: 1.5;
  color: #fff;
  opacity: 0.55;
  text-align: center;
}
.seg {
  display: flex;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 7px;
  cursor: pointer;
  transition: background .1s;
}
.seg:hover { background: rgba(255,255,255,0.09); }
.seg.active { background: rgba(0,80,252,0.28); }
.seg__time {
  flex-shrink: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: #fff;
  opacity: 0.55;
  padding-top: 2px;
  width: 44px;
}
.seg__text {
  flex: 1;
  font-size: 13.5px;
  line-height: 1.45;
  color: #fff;
}

/* ---------- Økt 2: redigering, bokser og eksport ---------- */
.export-row { display: flex; gap: 6px; }
.export-row .btn-tiny { flex: 1; }

.seg {
  display: flex;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 7px;
  transition: background .1s;
  cursor: default;
}
.seg:hover { background: rgba(255,255,255,0.06); }
.seg.active { background: rgba(0,80,252,0.22); }

.seg__time {
  flex-shrink: 0;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: #fff;
  opacity: 0.55;
  padding-top: 4px;
  width: 40px;
  text-align: left;
  cursor: pointer;
  background: none;
  border: 0;
}
.seg__time:hover { opacity: 1; text-decoration: underline; }

.seg__content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.seg__editor {
  font-size: 13.5px;
  line-height: 1.45;
  color: #fff;
  outline: none;
  border-radius: 4px;
  padding: 2px 4px;
  cursor: text;
}
.seg__editor:focus {
  background: rgba(255,255,255,0.1);
  box-shadow: 0 0 0 2px rgba(0,80,252,0.6);
}

.seg__preview {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}
.cap-box {
  display: inline-block;
  background: var(--faktisk-blue);
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 11px;
  line-height: 1.3;
  padding: 2px 7px;
  border-radius: 3px;
  white-space: nowrap;
}
.seg__warn {
  font-size: 11px;
  color: #FFB4B4;
  margin-top: 2px;
}

.seg__del {
  flex-shrink: 0;
  align-self: flex-start;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: rgba(255,255,255,0.12);
  color: #fff;
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  border: 0;
  opacity: 0;
  transition: opacity .12s;
}
.seg:hover .seg__del { opacity: 0.7; }
.seg__del:hover { opacity: 1 !important; background: rgba(255,80,80,0.6); }

/* Bokser oppå videoen. Plasseringen er lest ut av selve Motion-malen
   (Faktisk titler.moti): linjegruppene ligger på Y ≈ -267/-371/-474 i
   Motion-koordinater på 1080x1920-lerretet, dvs. at nederste linje
   starter ~25 % fra bunnen. */
.caption-overlay {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 25%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  pointer-events: none;
}
.cap-box--video {
  /* Størrelsen beregnes i JS fra malens 60 px på 1080-lerretet */
  font-size: var(--cap-font, 16px);
  padding: 0.12em 0.45em;
  border-radius: 0.12em;
  line-height: 1.25;
}
